window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7b41f1df66b6a596"]={"versions": [{"id": "FIG-7b41f1df66b6a596", "releases": ["R1.3.0", "R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Bitfeld- und Protokoll-Layout-Diagramm (Paketformat-Spezifikation) für das SOME/IP Service Discovery Protocol (SOME/IP-SD). Es definiert auf Bitebene die Header-Struktur eines SOME/IP-SD-Pakets mit einer 32-Bit-Breitenrasterung (Bit-Offset 0 bis 31). Das Format gliedert sich vertikal in den standardisierten SOME/IP-Basis-Header und den spezifischen SOME/IP-SD-Payload-Teil.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Nachrichtenformat umfasst folgende strukturierte Felder und Schichten:</p>\n<ul class=\"fig-list\">\n<li><strong>SOME/IP Header (Standardteil):</strong></li>\n<li><code>Message ID (Service ID / Method ID)</code> [32 Bit]: Aufgeteilt in Service-ID und Method-ID, mit festem Wert <code>0xFFFF 8100</code>.</li>\n<li><code>Length</code> [32 Bit]: Gesamtlänge in Byte ab dem darauffolgenden Feld bis zum Paketende.</li>\n<li><code>Request ID (Client ID / Session ID)</code> [32 Bit]: Kennung der Anfrage, bestehend aus Client ID und Session ID.</li>\n<li><code>Protocol Version</code> [8 Bit]: Protokollversion mit dem Festwert <code>=0x01</code>.</li>\n<li><code>Interface Version</code> [8 Bit]: Schnittstellenversion mit dem Festwert <code>=0x01</code>.</li>\n<li><code>Message Type</code> [8 Bit]: Nachrichtentyp mit dem Festwert <code>=0x02</code> (Notification).</li>\n<li><code>Return Code</code> [8 Bit]: Rückgabecode mit dem Festwert <code>=0x00</code> (E_OK).</li>\n<li><strong>SOME/IP-SD Teil (Payload):</strong></li>\n<li><code>Flags</code> [8 Bit]: Steuerflags für das Service Discovery.</li>\n<li><code>Reserved</code> [24 Bit]: Reserviertes Feld zur 32-Bit-Ausrichtung.</li>\n<li><code>Length of Entries Array</code> [32 Bit]: Längenangabe des nachfolgenden Entries-Arrays in Byte.</li>\n<li><code>Entries Array</code>: Dynamisches Array von SD-Einträgen (FindService, OfferService, SubscribeEventgroup etc.).</li>\n<li><code>Length of Options Array</code> [32 Bit]: Längenangabe des nachfolgenden Options-Arrays in Byte.</li>\n<li><code>Options Array</code>: Dynamisches Array von SD-Optionen (z. B. Konfigurations- oder Endpunkt-Parameter).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abbildung zeigt ein statisches Speicher- und Serialisierungslayout. Im Ablauf der Serialisierung bzw. Deserialisierung gilt:</p>\n<ol class=\"fig-list\">\n<li>Der SOME/IP-Standard-Header wird zuerst übertragen; das Feld <code>Length [32 bit]</code> deckt alle Bytes ab der <code>Request ID</code> bis zum Ende des <code>Options Array</code> ab.</li>\n<li>Der SD-Nutzlastteil beginnt mit den 8-Bit-Flags und 24 reservierten Bits.</li>\n<li>Danach wird das <code>Entries Array</code> anhand der vorangestellten Feldlänge <code>Length of Entries Array [32 bit]</code> geparst.</li>\n<li>Anschließend wird das <code>Options Array</code> anhand der Feldlänge <code>Length of Options Array [32 bit]</code> deserialisiert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend sind die festgelegten Bitbreiten, Offsets und festen Feldwerte:</p>\n<ul class=\"fig-list\">\n<li><code>Message ID</code>: Feste Service-ID <code>0xFFFF</code> und Method-ID <code>0x8100</code>.</li>\n<li>Feste Headerwerte: <code>Protocol Version = 0x01</code>, <code>Interface Version = 0x01</code>, <code>Message Type = 0x02</code>, <code>Return Code = 0x00</code>.</li>\n<li>Die Gültigkeitsbereiche der Längenfelder („Covered by Length“) sind strikt einzuhalten:</li>\n<li>SOME/IP <code>Length [32 bit]</code> umfasst alle nachfolgenden Bytes der gesamten Nachricht (Request ID bis Ende Options Array).</li>\n<li><code>Length of Entries Array</code> deckt exakt die Bytes des <code>Entries Array</code> ab.</li>\n<li><code>Length of Options Array</code> deckt exakt die Bytes des <code>Options Array</code> ab.</li>\n<li>Das 24-Bit-Feld <code>Reserved</code> muss gemäß Spezifikation belegt bzw. ignoriert werden.</li>\n</ul>"}, {"id": "FIG-3ea7a9341dec0414", "releases": ["R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist ein Bitfeld- und Protokoll-Layout-Diagramm (Paketformat-Spezifikation) für das SOME/IP Service Discovery Protocol (SOME/IP-SD). Es definiert auf Bitebene die Header-Struktur eines SOME/IP-SD-Pakets mit einer 32-Bit-Breitenrasterung (Bit-Offset 0 bis 31). Das Format gliedert sich vertikal in den standardisierten SOME/IP-Basis-Header und den spezifischen SOME/IP-SD-Payload-Teil.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Nachrichtenformat umfasst folgende strukturierte Felder und Schichten:</p>\n<ul class=\"fig-list\">\n<li><strong>SOME/IP Header (Standardteil):</strong></li>\n<li><code>Message ID (Service ID / Method ID)</code> [32 Bit]: Aufgeteilt in Service-ID und Method-ID, mit festem Wert <code>0xFFFF 8100</code>.</li>\n<li><code>Length</code> [32 Bit]: Gesamtlänge in Byte ab dem darauffolgenden Feld bis zum Paketende.</li>\n<li><code>Request ID (Client ID / Session ID)</code> [32 Bit]: Kennung der Anfrage, bestehend aus Client ID und Session ID.</li>\n<li><code>Protocol Version</code> [8 Bit]: Protokollversion mit dem Festwert <code>=0x01</code>.</li>\n<li><code>Interface Version</code> [8 Bit]: Schnittstellenversion mit dem Festwert <code>=0x01</code>.</li>\n<li><code>Message Type</code> [8 Bit]: Nachrichtentyp mit dem Festwert <code>=0x02</code> (Notification).</li>\n<li><code>Return Code</code> [8 Bit]: Rückgabecode mit dem Festwert <code>=0x00</code> (E_OK).</li>\n<li><strong>SOME/IP-SD Teil (Payload):</strong></li>\n<li><code>Flags</code> [8 Bit]: Steuerflags für das Service Discovery.</li>\n<li><code>Reserved</code> [24 Bit]: Reserviertes Feld zur 32-Bit-Ausrichtung.</li>\n<li><code>Length of Entries Array</code> [32 Bit]: Längenangabe des nachfolgenden Entries-Arrays in Byte.</li>\n<li><code>Entries Array</code>: Dynamisches Array von SD-Einträgen (FindService, OfferService, SubscribeEventgroup etc.).</li>\n<li><code>Length of Options Array</code> [32 Bit]: Längenangabe des nachfolgenden Options-Arrays in Byte.</li>\n<li><code>Options Array</code>: Dynamisches Array von SD-Optionen (z. B. Konfigurations- oder Endpunkt-Parameter).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Abbildung zeigt ein statisches Speicher- und Serialisierungslayout. Im Ablauf der Serialisierung bzw. Deserialisierung gilt:</p>\n<ol class=\"fig-list\">\n<li>Der SOME/IP-Standard-Header wird zuerst übertragen; das Feld <code>Length [32 bit]</code> deckt alle Bytes ab der <code>Request ID</code> bis zum Ende des <code>Options Array</code> ab.</li>\n<li>Der SD-Nutzlastteil beginnt mit den 8-Bit-Flags und 24 reservierten Bits.</li>\n<li>Danach wird das <code>Entries Array</code> anhand der vorangestellten Feldlänge <code>Length of Entries Array [32 bit]</code> geparst.</li>\n<li>Anschließend wird das <code>Options Array</code> anhand der Feldlänge <code>Length of Options Array [32 bit]</code> deserialisiert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend sind die festgelegten Bitbreiten, Offsets und festen Feldwerte:</p>\n<ul class=\"fig-list\">\n<li><code>Message ID</code>: Feste Service-ID <code>0xFFFF</code> und Method-ID <code>0x8100</code>.</li>\n<li>Feste Headerwerte: <code>Protocol Version = 0x01</code>, <code>Interface Version = 0x01</code>, <code>Message Type = 0x02</code>, <code>Return Code = 0x00</code>.</li>\n<li>Die Gültigkeitsbereiche der Längenfelder („Covered by Length“) sind strikt einzuhalten:</li>\n<li>SOME/IP <code>Length [32 bit]</code> umfasst alle nachfolgenden Bytes der gesamten Nachricht (Request ID bis Ende Options Array).</li>\n<li><code>Length of Entries Array</code> deckt exakt die Bytes des <code>Entries Array</code> ab.</li>\n<li><code>Length of Options Array</code> deckt exakt die Bytes des <code>Options Array</code> ab.</li>\n<li>Das 24-Bit-Feld <code>Reserved</code> muss gemäß Spezifikation belegt bzw. ignoriert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-7b41f1df66b6a596", "to": "FIG-3ea7a9341dec0414", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
